export function normalizeCertRecord(raw) {
  if (!raw) return null;
  return {
    id: raw.id || 0,
    certificate_number: raw.certificate_number || '',
    student_name: raw.student_name || 'Broadbeach Learner',
    candidate_email: raw.candidate_email || '',
    course_name: raw.course_name || 'Professional Certification',
    training_type: raw.training_type || 'Corporate Training',
    issuing_organization: raw.issuing_organization || 'Broadbeach Academy',
    authorized_signatory: raw.authorized_signatory || 'Dr. K. R. Sharma, Academic Director',
    issue_date: raw.issue_date || '2024-01-01',
    completion_date: raw.completion_date || raw.issue_date || '2024-01-01',
    status: raw.status || 'valid',
    verification_status: raw.status === 'revoked' ? 'Revoked' : 'Valid',
    validity: raw.validity || 'Lifetime',
    notes: raw.notes || 'Imported from corporate certificate master registry',
    history: raw.history || [
      {
        action: 'imported',
        timestamp: `${raw.issue_date || '2024-01-01'}T00:00:00Z`,
        performed_by: 'System Administrator',
        details: 'Batch imported into Master Certificate Registry.'
      }
    ]
  };
}

