const _DATA_STORE = {
  raw: RAW_REGISTRY,
  normalized: null,
  lookupMap: null,
  getRegistry() {
    if (!this.normalized) {
      this.normalized = this.raw.map(normalizeCertRecord);
    }
    return this.normalized;
  },
  getLookupMap() {
    if (!this.lookupMap) {
      const map = new Map();
      const list = this.getRegistry();
      for (let i = 0; i < list.length; i++) {
        const item = list[i];
        if (!item) continue;
        if (item.certificate_number) {
          const rawNum = String(item.certificate_number).trim();
          const upperNum = rawNum.toUpperCase();
          map.set(upperNum, item);
          const stripped = upperNum.replace(/[^A-Z0-9]/g, '');
          if (stripped && !map.has(stripped)) {
            map.set(stripped, item);
          }
        }
        if (item.id) {
          map.set(String(item.id), item);
        }
      }
      this.lookupMap = map;
    }
    return this.lookupMap;
  },
  find(query) {
    if (!query) return null;
    const clean = String(query).trim().toUpperCase();
    const map = this.getLookupMap();
    if (map.has(clean)) return map.get(clean);
    const stripped = clean.replace(/[^A-Z0-9]/g, '');
    if (stripped && map.has(stripped)) return map.get(stripped);
    // Scan by name fallback
    const list = this.getRegistry();
    for (let i = 0; i < list.length; i++) {
      const c = list[i];
      if (!c) continue;
      const cNum = String(c.certificate_number || '').trim().toUpperCase();
      if (cNum === clean || cNum.replace(/[^A-Z0-9]/g, '') === stripped) return c;
      const sName = String(c.student_name || '').trim().toUpperCase();
      if (sName && sName === clean) return c;
    }
    return null;
  }
};

export const MANUAL_CERTIFICATES_REGISTRY = _DATA_STORE.getRegistry();

export function getManualCertificatesRegistry() {
  return _DATA_STORE.getRegistry();
}

export function findManualCertificate(query) {
  return _DATA_STORE.find(query);
}

export default MANUAL_CERTIFICATES_REGISTRY;
